-- Metric view over sales.FactNewBusiness: the measures of the fact, sliced by
-- its own columns and those of the dimensions it references.
-- Columns marked meta.pii are left out.
-- Generated by `python -m dbde render` from models/gold/sales/FactNewBusiness.yml. Do not edit: change the spec and render again.

CREATE OR REPLACE VIEW ${gold_catalog}.sales.MetricNewBusiness
WITH METRICS
LANGUAGE YAML
AS $$
version: '1.1'
comment: 'Metric view of FactNewBusiness (measures: NewBusinessCount, AnnualPremiumTotal);
  query with MEASURE(<name>) and GROUP BY ALL. One row per issued new business
  policy. Grain = Policy_BK.'
source: ${gold_catalog}.sales.FactNewBusiness
joins:
- name: DimAgent
  source: ${gold_catalog}.distribution.DimAgent
  'on': source.DimAgent_SK = DimAgent.DimAgent_SK
dimensions:
- name: Policy_BK
  expr: source.Policy_BK
  comment: Policy number.
- name: ProductCode
  expr: source.ProductCode
  comment: Product code.
  synonyms:
  - Product
  - Plan
- name: IssueDate
  expr: source.IssueDate
  comment: Date the policy was issued.
- name: Agent_BK
  expr: DimAgent.Agent_BK
  comment: Agent code from the policy admin system.
- name: BranchCode
  expr: DimAgent.BranchCode
  comment: Branch the agent belongs to.
- name: IsActive
  expr: DimAgent.IsActive
  comment: True when the agent may write new business.
measures:
- name: NewBusinessCount
  expr: count(Policy_BK)
  comment: Number of new business policies issued.
  synonyms:
  - Policies sold
  - Policy count
- name: AnnualPremiumTotal
  expr: sum(AnnualPremiumAmount)
  comment: Total annualised premium of new business.
  synonyms:
  - Total premium
  - New business premium
$$;
